import { CetusTooltip } from '@cetus/design'
import useWindowWidth from '@cetus/hooks/src/useWindowWidth'
import { Icon } from '@cetus/ui-kit'
import { HStack, Image, ImageProps, Text, VStack } from '@chakra-ui/react'
import { useState } from 'react'

type VaultsFarmIconProps = {
  imageStyle?: ImageProps
}
export default function VaultsFarmIcon(props: VaultsFarmIconProps) {
  const { imageStyle } = props
  const [accessHover, setAccessHover] = useState(false)
  const [showTooltip, setShowTooltip] = useState(false)
  const { isApp } = useWindowWidth()
  return (
    <CetusTooltip
      tooltip={
        <VStack p="4px 4px 0">
          <Text fontSize="12px" color="text_caption">
            Farming Rewards Available on Haedal
          </Text>

          <HStack
            gap="0"
            cursor="pointer"
            onMouseMove={() => {
              setAccessHover(true)
            }}
            onMouseLeave={() => {
              setAccessHover(false)
            }}
            onClick={e => {
              e.stopPropagation()
              window.open('https://www.haedal.xyz/farms', '_blank')
            }}
          >
            <Text fontSize="12px" color={accessHover ? 'text_caption' : 'text_paragraph'}>
              Access
            </Text>
            <Icon xlinkHref="#icon-icon_ascending_nor" transform="rotate(90deg)" svgFill={accessHover ? 'text_caption' : 'text_paragraph'} />
          </HStack>
        </VStack>
      }
    >
      <Image src="/images/icon_farms.png" w="16px" h="16px" {...imageStyle} />
    </CetusTooltip>
  )
}
